et\/2022-04-05-COACH-Simon-Phillips-103-1649325817.jpg\",\"position\":1},{\"id\":222257,\"content_id\":352556,\"key\":\"coach_featured_image\",\"value\":\"https:\/\/d1923uyy6spedc.cloudfront.net\/2022-04-05-COACH-Simon-Phillips-127-1649325826.jpg\",\"position\":1},{\"id\":222258,\"content_id\":352556,\"key\":\"coach_top_banner_image\",\"value\":\"https:\/\/d1923uyy6spedc.cloudfront.net\/2022-04-05-COACH-Simon-Phillips-127-1649325826.jpg\",\"position\":1},{\"id\":222259,\"content_id\":352556,\"key\":\"coach_bottom_banner_image\",\"value\":\"https:\/\/d1923uyy6spedc.cloudfront.net\/2022-04-05-COACH-Simon-Phillips-127-1649325826.jpg\",\"position\":1},{\"id\":222175,\"content_id\":352556,\"key\":\"focus_text\",\"value\":\"Legendary Drum Sounds\",\"position\":1},{\"id\":222200,\"content_id\":352556,\"key\":\"short_bio\",\"value\":\"&lt;p&gt;Known as one of the world&#039;s most respected and revered drummers, Simon Phillips has recorded and performed with such legendary acts as Toto, Jeff Beck, Hiromi, Pete Townshend, and with his own group, Protocol.&lt;\/p&gt;\",\"position\":1},{\"id\":222201,\"content_id\":352556,\"key\":\"long_bio\",\"value\":\"&lt;p&gt;Simon Phillips has been a household name in the drumming community for decades. Known for his incredible groove, virtuosic chops, and iconic drum sound, he has been one of the most prolific musicians of his generation. Simon has performed with Toto, Jeff Beck, Hiromi, Pete Townshend, Judas Priest, with his own group, Protocol, and as a session drummer with countless more artists. &lt;\/p&gt;&lt;p&gt;&lt;br&gt;&lt;\/p&gt;&lt;p&gt;Beyond his drumming prowess, Simon is also an accomplished producer and audio engineer. In this role, his depth of studio knowledge and distinct musical sensibility has served an entire new generation of musical artists.&lt;\/p&gt;\",\"position\":1}],\"permissions\":[],\"current_user_is_subscribed\":false,\"coach_profile_image\":\"https:\/\/d1923uyy6spedc.cloudfront.net\/2022-04-05-COACH-Simon-Phillips-114-1649325767.jpg\",\"name\":\"Simon Phillips\"},\"type\":\"content\",\"position\":1}],\"data\":[{\"id\":222380,\"content_id\":352738,\"key\":\"original_thumbnail_url\",\"value\":\"https:\/\/d1923uyy6spedc.cloudfront.net\/simon-phillips-live-Members(1)-1649446210.jpg\",\"position\":1},{\"id\":222381,\"content_id\":352738,\"key\":\"thumbnail_url\",\"value\":\"https:\/\/d1923uyy6spedc.cloudfront.net\/simon-phillips-live-Members(1)-1649446210.jpg\",\"position\":1},{\"id\":222451,\"content_id\":352738,\"key\":\"description\",\"value\":\"&lt;p&gt;In this live session, Simon explores how he creates his legendary drum sound through means of tuning, kit set-up, and self-mixing. We\u2019ll also dive into a more broad discussion around the idea of being a musical drummer. Plus, he\u2019ll be performing some of his most iconic tracks - both new and old. You don&#039;t want to miss this one!&lt;\/p&gt;\",\"position\":1}],\"permissions\":[{\"id\":1,\"content_id\":null,\"content_type\":\"live\",\"permission_id\":1,\"brand\":\"drumeo\",\"name\":\"Drumeo Edge\"}],\"user_progress\":{\"483949\":[]},\"completed\":false,\"started\":false,\"progress_percent\":0,\"live_event_start_time_in_timezone\":\"2022-04-08 15:00:00\",\"live_event_end_time_in_timezone\":\"2022-04-08 16:15:00\",\"published_on_in_timezone\":\"2022-04-08 15:00:00\",\"instructors\":[\"Simon Phillips\"],\"coaches\":[{\"id\":352556,\"popularity\":0,\"slug\":\"simon-phillips\",\"type\":\"instructor\",\"sort\":0,\"status\":\"published\",\"language\":\"en-US\",\"brand\":\"drumeo\",\"total_xp\":\"150\",\"published_on\":\"2022-04-06 10:05:20\",\"created_on\":\"2022-04-06 10:05:20\",\"archived_on\":null,\"parent_id\":null,\"child_id\":null,\"fields\":[{\"id\":537247,\"content_id\":352556,\"key\":\"show_in_new_feed\",\"value\":\"1\",\"type\":\"boolean\",\"position\":1},{\"id\":537248,\"content_id\":352556,\"key\":\"name\",\"value\":\"Simon Phillips\",\"type\":\"string\",\"position\":1},{\"id\":537305,\"content_id\":35